ee:variables.ee:set-variable:
%dw 2.0
output application/java
var enrichMode = upper((p("external.register.mode") default "INLINE") as String)
var base = {
  id: vars.newPartyId,
  href: "http://localhost:8081/api/party/" ++ vars.newPartyId,
  "@type": "Organization",
  "@baseType": "Party",
  companyName: vars.incoming.companyName default vars.incoming.name,
  name: vars.incoming.name default vars.incoming.companyName,
  registrationNumber: vars.incoming.registrationNumber,
  legalAddress: vars.incoming.legalAddress default {},
  representative: vars.incoming.representative default {},
  status: "created",
  createdAt: now() as String
}
---
if (enrichMode == "INLINE" and (vars.incoming.externalRegisterData default null) != null)
  base ++ {externalRegisterData: vars.incoming.externalRegisterData}
else if (enrichMode == "LINK" and (vars.incoming.externalRegisterRef default null) != null)
  base ++ {externalRegisterRef: vars.incoming.externalRegisterRef}
else
  base

%dw 2.0
output application/json
---
{
  eventId: uuid(),
  eventType: vars.eventType,
  eventTime: now() as String,
  event: {
    party: payload
  }
}
